"""Offline Apple OFF installation/never-used removal generator. No DB connection."""
from pathlib import Path
import re,json,hashlib,argparse
ROOT=Path(__file__).resolve().parent
MODS=['apple_owner_policy','apple_google_protection','apple_native_enrollment_private','apple_existing_login_private']
GUARD='apple_deployment_guard'
TABLES=['auth.users','auth.identities','auth.sessions','public.company_members','private.account_deletion_access_restrictions']
APIS=['public.read_apple_native_enrollment_context(uuid,uuid)','public.reserve_apple_native_subject(uuid,uuid,text,text,text,text,bigint)','public.complete_apple_native_subject(uuid,uuid,uuid,text,text,text)','public.hold_apple_native_subject(uuid,uuid,uuid)','public.resolve_existing_apple_login(text)','public.consume_existing_apple_login(text,text)']
SOURCES=['owner-policy.sql.review-only','google-protection.sql.review-only','native-enrollment.sql.review-only','registered-apple-login.sql.review-only','native-enrollment-recovery.sql.review-only']
def q(x):return "'"+str(x).replace("'","''")+"'"
def arr(xs):return 'array['+','.join(q(x)for x in xs)+']::text[]'
def catalog(relations,old=False):
 omit="and t.tgname<>'sko_google_apple_identity_guard'"if old else ''
 return """select coalesce(jsonb_agg(jsonb_build_object('oid',c.oid,'owner',c.relowner,'acl',c.relacl,'rls',c.relrowsecurity,'forcerls',c.relforcerowsecurity,'kind',c.relkind,
'columns',(select jsonb_agg(to_jsonb(a)||jsonb_build_object('default',pg_get_expr(d.adbin,d.adrelid))order by a.attnum)from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0),
'constraints',(select jsonb_agg(to_jsonb(k)order by oid)from pg_constraint k where k.conrelid=c.oid),
'indexes',(select jsonb_agg(to_jsonb(i)order by indexrelid)from pg_index i where i.indrelid=c.oid),
'triggers',(select jsonb_agg(to_jsonb(t)order by oid)from pg_trigger t where t.tgrelid=c.oid """+omit+"""),
'policies',(select jsonb_agg(to_jsonb(p)order by oid)from pg_policy p where p.polrelid=c.oid))order by c.oid),'[]')from pg_class c where c.oid in(select to_regclass(x)from unnest("""+relations+")x)"
CAT=catalog(arr(TABLES));OLD_CAT=catalog(arr(TABLES),True)
HELPERS="select jsonb_agg(to_jsonb(p)order by oid)from pg_proc p where p.oid in(to_regprocedure('auth.uid()'),to_regprocedure('auth.jwt()'))"
BASESCHEMAS="select jsonb_agg(to_jsonb(n)order by oid)from pg_namespace n where nspname in('auth','private','public')"
DEFAULTS="select coalesce(jsonb_agg(to_jsonb(d)order by oid),'[]')from pg_default_acl d"
def md5select(sql):return '(select md5(('+sql+')::text))'
CAPTURE="select jsonb_build_object('operator',current_user,'session_user',session_user,'catalogue_md5',"+md5select(CAT)+",'helpers_md5',"+md5select(HELPERS)+",'schemas_md5',"+md5select(BASESCHEMAS)+",'default_acl_md5',"+md5select(DEFAULTS)+",'module_absent',not exists(select 1 from pg_namespace where nspname=any("+arr(MODS+[GUARD])+")),'api_absent',not exists(select 1 from unnest("+arr(APIS)+")x where to_regprocedure(x)is not null),'trigger_privilege',has_table_privilege(current_user,'auth.identities','TRIGGER'),'drop_trigger_grants',current_setting('supautils.drop_trigger_grants',true))snapshot;"
def equal(sql,h,tag):return 'if '+md5select(sql)+'is distinct from '+q(h)+"then raise exception '"+tag+"';end if;"
def rows(before):
 if before:return "create temporary table apple_guard_rows(relation text,n bigint,h text)on commit drop;do $rows$ declare r text;n bigint;h text;begin foreach r in array "+arr(TABLES)+"loop execute format($q$select count(*)::bigint,md5(coalesce(string_agg(h,''order by h),''))from(select md5(to_jsonb(x)::text)h from %s x)d$q$,r)into n,h;insert into pg_temp.apple_guard_rows values(r,n,h);end loop;end $rows$;"
 return "do $rows$ declare r record;n bigint;h text;begin for r in select * from pg_temp.apple_guard_rows loop execute format($q$select count(*)::bigint,md5(coalesce(string_agg(h,''order by h),''))from(select md5(to_jsonb(x)::text)h from %s x)d$q$,r.relation)into n,h;if n is distinct from r.n or h is distinct from r.h then raise exception 'apple_existing_rows_changed';end if;end loop;end $rows$;"
def compose(s,source):
 if s['operator']!='postgres'or s['session_user']!='postgres'or not s['module_absent']or not s['api_absent']or not s['trigger_privilege']:raise ValueError('fresh postgres catalogue required')
 bodies=[];hashes={}
 for name in SOURCES:
  b=(source/name).read_text();hashes[name]=hashlib.sha256(b.encode()).hexdigest()
  if len(re.findall(r'^begin;\s*$',b,re.M))!=1 or len(re.findall(r'^commit;\s*$',b,re.M))!=1:raise ValueError('component transaction')
  bodies.append(re.sub(r'^(?:begin|commit);\s*$','',b,flags=re.M))
 prefix=['-- REVIEW ONLY. No activation, Auth config, signature or identity-row mutation.','begin;',"set local search_path='';set local lock_timeout='5s';set local statement_timeout='45s';",'lock table '+','.join(TABLES)+' in access exclusive mode;']
 check="do $before$ begin if current_user<>'postgres'or session_user<>'postgres'then raise exception 'apple_operator';end if;if exists(select 1 from pg_namespace where nspname=any("+arr(MODS+[GUARD])+"))then raise exception 'apple_module_exists';end if;"
 check+=''.join('if to_regprocedure('+q(x)+")is not null then raise exception 'apple_api_exists';end if;"for x in APIS)
 check+=equal(CAT,s['catalogue_md5'],'apple_catalogue_drift')+equal(HELPERS,s['helpers_md5'],'apple_helper_drift')+equal(BASESCHEMAS,s['schemas_md5'],'apple_schema_acl_drift')+equal(DEFAULTS,s['default_acl_md5'],'apple_default_acl_drift')
 check+="if not has_table_privilege(current_user,'auth.identities','TRIGGER')then raise exception 'apple_trigger_privilege';end if;if not exists(select 1 from pg_roles where rolname=current_user and rolsuper)and not pg_has_role(current_user,(select relowner from pg_class where oid='auth.identities'::regclass),'MEMBER')and not coalesce((current_setting('supautils.drop_trigger_grants',true)::jsonb->current_user)?'auth.identities',false)then raise exception 'apple_drop_trigger_privilege';end if;end $before$;"
 allmods=arr(MODS+[GUARD]);rels="array(select n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+allmods+")and c.relkind in('r','p'))"
 funcs="select jsonb_agg(to_jsonb(p)order by p.oid)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any("+allmods+")or p.oid in(select to_regprocedure(x)from unnest("+arr(APIS)+")x)"
 seq="select coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'name',sequencename,'value',last_value)order by schemaname,sequencename),'[]')from pg_sequences where schemaname=any("+allmods+")"
 out=prefix+[check,rows(True),*bodies]
 out += ["create schema apple_deployment_guard;revoke all on schema apple_deployment_guard from public,anon,authenticated,service_role;create table apple_deployment_guard.receipt(singleton boolean primary key check(singleton),ever_used boolean not null default false,catalogue jsonb not null,functions jsonb not null,sequences jsonb not null);alter table apple_deployment_guard.receipt enable row level security;revoke all on apple_deployment_guard.receipt from public,anon,authenticated,service_role;",
 "create function apple_deployment_guard.mark_used()returns trigger language plpgsql security definer set search_path='' as $$begin update apple_deployment_guard.receipt set ever_used=true where singleton and not ever_used;return null;end$$;revoke all on function apple_deployment_guard.mark_used()from public,anon,authenticated,service_role;",
 "do $marks$ declare t record;begin for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')loop execute format('create trigger apple_deployment_used before insert or update or delete or truncate on %I.%I for each statement execute function apple_deployment_guard.mark_used()',t.nspname,t.relname);end loop;end $marks$;"]
 owncat="select jsonb_build_object('schemas',(select jsonb_agg(to_jsonb(n)order by oid)from pg_namespace n where nspname=any("+allmods+")),'relations',("+catalog(rels)+"),'auth',("+CAT+"))"
 out += ["create function apple_deployment_guard.catalogue()returns jsonb language sql stable security definer set search_path='' as $$"+owncat+"$$;revoke all on function apple_deployment_guard.catalogue()from public,anon,authenticated,service_role;",
 "do $access$ declare n text;f text;t record;used boolean;begin foreach n in array "+allmods+"loop if has_schema_privilege('anon',n,'USAGE')or has_schema_privilege('authenticated',n,'USAGE')or has_schema_privilege('service_role',n,'USAGE')then raise exception 'apple_private_schema_acl';end if;end loop;foreach f in array "+arr(APIS)+"loop if has_function_privilege('anon',f,'EXECUTE')or has_function_privilege('authenticated',f,'EXECUTE')or not has_function_privilege('service_role',f,'EXECUTE')then raise exception 'apple_public_api_acl';end if;end loop;for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')loop execute format('select exists(select 1 from %I.%I)',t.nspname,t.relname)into used;if used then raise exception 'apple_rollout_or_state_seeded';end if;end loop;end $access$;",
 "do $after$ begin "+equal(OLD_CAT,s['catalogue_md5'],'apple_auth_catalogue_changed')+equal(HELPERS,s['helpers_md5'],'apple_auth_helper_changed')+equal(BASESCHEMAS,s['schemas_md5'],'apple_schema_acl_changed')+"end $after$;",rows(False),"insert into apple_deployment_guard.receipt(singleton,catalogue,functions,sequences)values(true,apple_deployment_guard.catalogue(),("+funcs+"),("+seq+"));",'commit;']
 restore=prefix+["lock table apple_deployment_guard.receipt in access exclusive mode;do $locks$ declare t record;begin for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')order by n.nspname,c.relname loop execute format('lock table %I.%I in access exclusive mode',t.nspname,t.relname);end loop;end $locks$;",rows(True),
 "do $unused$ declare r apple_deployment_guard.receipt%rowtype;t record;used boolean;begin if current_user<>'postgres'or session_user<>'postgres'then raise exception 'apple_operator';end if;if current_setting('sko.apple_restore_hooks_and_endpoints_unconfigured',true)is distinct from 'true'then raise exception 'apple_hosted_configuration_attestation_required';end if;select * into strict r from apple_deployment_guard.receipt;if r.ever_used or r.catalogue is distinct from apple_deployment_guard.catalogue()or r.functions is distinct from ("+funcs+")or r.sequences is distinct from ("+seq+")then raise exception 'apple_used_or_catalogue_changed';end if;for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')loop execute format('select exists(select 1 from %I.%I)',t.nspname,t.relname)into used;if used then raise exception 'apple_used_restore_refused';end if;end loop;if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where not(n.nspname=any("+allmods+"))and p.oid not in(select to_regprocedure(x)from unnest("+arr(APIS)+")x)and (p.prosrc||coalesce(array_to_string(p.proconfig,','),''))~*'apple_(owner_policy|google_protection|native_enrollment_private|existing_login_private|deployment_guard)[.]|read_apple_native_enrollment_context|reserve_apple_native_subject|complete_apple_native_subject|hold_apple_native_subject|resolve_existing_apple_login|consume_existing_apple_login')then raise exception 'apple_external_runtime_dependency';end if;end $unused$;",
 'drop trigger sko_google_apple_identity_guard on auth.identities;']
 restore += ['drop function '+f+' restrict;'for f in reversed(APIS)]
 restore += ["do $triggers$ declare t record;begin for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')loop execute format('drop trigger apple_deployment_used on %I.%I',t.nspname,t.relname);end loop;end $triggers$;","do $tables$ declare t record;progress boolean;begin loop progress:=false;for t in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p')loop begin execute format('drop table %I.%I restrict',t.nspname,t.relname);progress:=true;exception when dependent_objects_still_exist then null;end;end loop;exit when not progress;end loop;if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any("+arr(MODS)+")and c.relkind in('r','p'))then raise exception 'apple_unknown_table_dependency';end if;end $tables$;","do $functions$ declare f record;progress boolean;begin loop progress:=false;for f in select p.oid::regprocedure::text signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any("+arr(MODS)+")loop begin execute 'drop function '||f.signature||' restrict';progress:=true;exception when dependent_objects_still_exist then null;end;end loop;exit when not progress;end loop;if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any("+arr(MODS)+"))then raise exception 'apple_unknown_function_dependency';end if;end $functions$;"]
 restore += ['drop schema '+n+' restrict;'for n in reversed(MODS)]
 restore += ["drop function apple_deployment_guard.catalogue();drop function apple_deployment_guard.mark_used();drop table apple_deployment_guard.receipt;drop schema apple_deployment_guard restrict;",
 "do $restored$ begin "+equal(CAT,s['catalogue_md5'],'apple_original_catalogue_not_restored')+equal(HELPERS,s['helpers_md5'],'apple_original_helpers_not_restored')+equal(BASESCHEMAS,s['schemas_md5'],'apple_original_schema_not_restored')+"end $restored$;",rows(False),'commit;']
 return '\n'.join(out)+'\n','\n'.join(restore)+'\n',hashes
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--snapshot');p.add_argument('--source-root',default=str(ROOT.parent.parent/'apple-login-candidate/broker'));a=p.parse_args();(ROOT/'capture.sql').write_text(CAPTURE+'\n')
 if a.snapshot:
  d=json.loads(Path(a.snapshot).read_text());s=d.get('snapshot',d)if isinstance(d,dict)else d[0]['snapshot'];i,r,h=compose(s,Path(a.source_root));(ROOT/'install-off.guarded.sql.review-only').write_text(i);(ROOT/'restore-unused.guarded.sql.review-only').write_text(r);(ROOT/'manifest.json').write_text(json.dumps(dict(source_hashes=h,install_sha256=hashlib.sha256(i.encode()).hexdigest(),restore_sha256=hashlib.sha256(r.encode()).hexdigest(),production_changed=False),indent=2)+'\n')
